using System;using System.IO;using System.IO.Compression;using System.Net;using System.Net.Http;using System.Text;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Security.Cryptography;
[assembly:System.Reflection.AssemblyVersion("1.0.0.0")]
namespace LightExcerptUpdate {
public class Manifest{public string version{get;set;}public string packageUrl{get;set;}public string sha256{get;set;}public long size{get;set;}public string releaseNotes{get;set;}}
public static class Core {
public static readonly string[] RootFiles={"轻摘.exe","轻摘更新.exe","Microsoft.Web.WebView2.Core.dll","Microsoft.Web.WebView2.WinForms.dll","WebView2Loader.dll","version.json","README.md","启动轻摘.cmd","导入旧资料.cmd","导入旧资料.ps1","THIRD-PARTY-NOTICES.md"};
public static Version VersionOf(string value){Version v;if(!Version.TryParse((value??"").TrimStart('v','V'),out v)||v.Major<1)throw new Exception("更新版本号无效");return v;}
public static void Validate(Manifest m,bool local){if(m==null)throw new Exception("更新清单为空");VersionOf(m.version);if(m.size<1||m.size>2L*1024*1024*1024)throw new Exception("更新包大小无效或超过2GB");if(m.sha256==null||!System.Text.RegularExpressions.Regex.IsMatch(m.sha256,"^[a-fA-F0-9]{64}$"))throw new Exception("更新清单缺少有效SHA-256");if(!Url(m.packageUrl,local))throw new Exception("更新包地址必须是HTTPS");}
public static bool Url(string value,bool local){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&string.IsNullOrEmpty(u.UserInfo)&&(u.Scheme=="https"||(local&&u.Scheme=="http"&&u.IsLoopback));}
public static string SafePath(string root,string relative){string r=relative.Replace('\\','/');if(r.StartsWith("/")||r.Contains(":")||r.IndexOf('\0')>=0)throw new Exception("更新包包含非法路径");var parts=r.Split('/');foreach(string part in parts)if(part==".."||part=="."||part.EndsWith(" ")||part.EndsWith(".")||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new Exception("更新包路径不安全");bool allowed=r.StartsWith("app/",StringComparison.OrdinalIgnoreCase)||r.StartsWith("runtime/",StringComparison.OrdinalIgnoreCase)||Array.Exists(RootFiles,x=>x.Equals(r,StringComparison.OrdinalIgnoreCase));if(!allowed)throw new Exception("更新包尝试写入受保护或未知目录："+r);string full=Path.GetFullPath(Path.Combine(root,r));string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("文件路径越界");string current=root;foreach(string part in parts){if(part.Length==0)continue;current=Path.Combine(current,part);if((Directory.Exists(current)||File.Exists(current))&&(File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new Exception("目标路径含链接，不能更新");}return full;}
public static List<string> Extract(string zip,string stage){var list=new List<string>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;using(var archive=ZipFile.OpenRead(zip)){if(archive.Entries.Count>20000)throw new Exception("更新包文件过多");foreach(var entry in archive.Entries){string relative=entry.FullName.Replace('\\','/');if(relative.EndsWith("/"))continue;if(!seen.Add(relative))throw new Exception("更新包存在重复文件");if(((entry.ExternalAttributes>>16)&0xF000)==0xA000)throw new Exception("更新包不能包含符号链接");string dest=SafePath(stage,relative);total+=entry.Length;if(entry.Length>1024L*1024*1024||total>3L*1024*1024*1024)throw new Exception("更新包解压体积过大");Directory.CreateDirectory(Path.GetDirectoryName(dest));entry.ExtractToFile(dest);list.Add(relative);}}if(!list.Contains("轻摘.exe")||!list.Contains("version.json")||!list.Contains("app/server.cjs")||!list.Contains("runtime/node.exe"))throw new Exception("更新包缺少必需文件");return list;}
public static async Task DownloadAndVerify(HttpClient client,Manifest manifest,string zip,bool local,Action<string,long,double> report){Validate(manifest,local);long received=0,last=0,lastMs=0;var watch=Stopwatch.StartNew();using(var response=await client.GetAsync(manifest.packageUrl,HttpCompletionOption.ResponseHeadersRead)){if(!response.IsSuccessStatusCode)throw new Exception("下载HTTP "+(int)response.StatusCode);if(!Url(response.RequestMessage.RequestUri.ToString(),local))throw new Exception("下载重定向到不安全地址");if(response.Content.Headers.ContentLength.HasValue&&response.Content.Headers.ContentLength.Value!=manifest.size)throw new Exception("更新包大小与清单不一致");using(var input=await response.Content.ReadAsStreamAsync())using(var output=File.Create(zip)){byte[] buffer=new byte[131072];int read;while((read=await input.ReadAsync(buffer,0,buffer.Length))>0){received+=read;if(received>manifest.size)throw new Exception("下载数据超过声明大小");await output.WriteAsync(buffer,0,read);if(watch.ElapsedMilliseconds-lastMs>=150){double seconds=Math.Max(.001,(watch.ElapsedMilliseconds-lastMs)/1000.0);report("download",received,(received-last)/seconds);last=received;lastMs=watch.ElapsedMilliseconds;}}}}if(received!=manifest.size)throw new Exception("下载不完整，未替换文件");report("verify",received,0);string hash=await Task.Run(()=>Hash(zip));if(!hash.Equals(manifest.sha256,StringComparison.OrdinalIgnoreCase))throw new Exception("完整性校验失败，未替换文件");report("verified",received,0);}
public static async Task NodeDownload(string root,JavaScriptSerializer json,bool localTest,string source,string destination,long limit,Action<long,double> report){string node=Path.Combine(root,"runtime","node.exe"),helper=Path.Combine(root,"app","update-download.cjs");if(!File.Exists(node)||!File.Exists(helper))throw new Exception("下载运行时缺失，请从完整发布包恢复runtime与app/update-download.cjs");string arguments="\""+helper+"\" --url \""+new Uri(source).AbsoluteUri+"\" --out \""+destination+"\" --limit "+limit+(localTest?" --local-test 1":"");using(var proc=new Process{StartInfo=new ProcessStartInfo(node,arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){proc.Start();var errors=proc.StandardError.ReadToEndAsync();string line;while((line=await proc.StandardOutput.ReadLineAsync())!=null){if(line.Length>10000)continue;try{var item=json.Deserialize<Dictionary<string,object>>(line);if(report!=null&&Convert.ToString(item["type"])=="progress")report(Convert.ToInt64(item["received"]),Convert.ToDouble(item["bytesPerSecond"]));}catch{}}await Task.Run(()=>proc.WaitForExit());string error=await errors;if(proc.ExitCode!=0)throw new Exception(string.IsNullOrWhiteSpace(error)?"下载失败":error.Trim());}}
public static string Hash(string file){using(var stream=File.OpenRead(file))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
public static void Apply(string root,string stage,string backup,List<string> files,Action<int,int> progress){var touched=new List<string>();try{int i=0;foreach(var relative in files){string dest=SafePath(root,relative),src=SafePath(stage,relative),old=SafePath(backup,relative);if(File.Exists(dest)){Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(dest,old,true);}touched.Add(relative);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(src,dest,true);progress(++i,files.Count);}}catch{for(int i=touched.Count-1;i>=0;i--){string r=touched[i],dest=SafePath(root,r),old=SafePath(backup,r);try{if(File.Exists(old))File.Copy(old,dest,true);else if(File.Exists(dest))File.Delete(dest);}catch{}}throw new Exception("替换失败，已尝试回滚。请保留UserData/updates中的备份，勿删除数据目录。");}}
}
static class Program{[STAThread]static int Main(string[] args){if(args.Length>0&&args[0]=="--self-test"){try{SelfTest();Console.WriteLine("PASS updater integrity/path/extract/rollback");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(Path.GetTempPath(),"LightExcerpt-update-test-error.txt"),e.ToString());return 1;}}if(args.Length==3&&args[0]=="--exercise"){string testRoot=Path.GetFullPath(args[2]);string tempRoot=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!testRoot.StartsWith(tempRoot,StringComparison.OrdinalIgnoreCase))return 3;try{Exercise(args[1],testRoot).GetAwaiter().GetResult();File.WriteAllText(Path.Combine(testRoot,"test-result.txt"),"PASS");return 0;}catch(Exception ex){Directory.CreateDirectory(testRoot);File.WriteAllText(Path.Combine(testRoot,"test-result.txt"),ex.Message);return 2;}}ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;string self=System.Reflection.Assembly.GetExecutingAssembly().Location;if(File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"version.json"))&&File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app","server.cjs"))){string temp=Path.Combine(Path.GetTempPath(),"LightExcerptUpdater-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(self,temp);Process.Start(new ProcessStartInfo(temp,"--root \""+AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\')+"\""){UseShellExecute=true});return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new UpdateForm(args));return 0;}
static async Task Exercise(string manifestUrl,string root){if(!Core.Url(manifestUrl,true)||!new Uri(manifestUrl).IsLoopback)throw new Exception("test requires loopback");Directory.CreateDirectory(root);using(var http=new HttpClient()){var serializer=new JavaScriptSerializer();string manifestFile=Path.Combine(root,"manifest.json");await Core.NodeDownload(AppDomain.CurrentDomain.BaseDirectory,serializer,true,manifestUrl,manifestFile,1024*1024,null);var m=serializer.Deserialize<Manifest>(File.ReadAllText(manifestFile));string zip=Path.Combine(root,"test-package.zip"),stage=Path.Combine(root,"stage"),install=Path.Combine(root,"installed"),backup=Path.Combine(root,"backup");Core.Validate(m,true);await Core.NodeDownload(AppDomain.CurrentDomain.BaseDirectory,serializer,true,m.packageUrl,zip,m.size,null);if(new FileInfo(zip).Length!=m.size||!Core.Hash(zip).Equals(m.sha256,StringComparison.OrdinalIgnoreCase))throw new Exception("完整性校验失败");var files=Core.Extract(zip,stage);var embedded=serializer.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(stage,"version.json")));if(Core.VersionOf(Convert.ToString(embedded["version"]))!=Core.VersionOf(m.version))throw new Exception("version mismatch");Core.Apply(install,stage,backup,files,(i,n)=>{});}}
static void SelfTest(){string root=Path.Combine(Path.GetTempPath(),"LightExcerpt-update-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string[] bad={"../x","UserData/data.json","app/../../x","C:/x","app/x.","app/test:bad"};foreach(var b in bad){bool rejected=false;try{Core.SafePath(root,b);}catch{rejected=true;}if(!rejected)throw new Exception("unsafe path accepted "+b);}Core.Validate(new Manifest{version="1.0.1",packageUrl="https://github.com/u/r/releases/download/v1.0.1/update.zip",size=10,sha256=new string('a',64)},false);string f=Path.Combine(root,"hash.txt");File.WriteAllText(f,"abc",new UTF8Encoding(false));if(Core.Hash(f)!="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")throw new Exception("hash mismatch");string stage=Path.Combine(root,"stage"),target=Path.Combine(root,"target"),backup=Path.Combine(root,"backup");Directory.CreateDirectory(Path.Combine(stage,"app"));Directory.CreateDirectory(Path.Combine(target,"app"));File.WriteAllText(Path.Combine(stage,"app/a.txt"),"new");File.WriteAllText(Path.Combine(target,"app/a.txt"),"old");File.WriteAllText(Path.Combine(target,"UserData.txt"),"preserved");bool failed=false;try{Core.Apply(target,stage,backup,new List<string>{"app/a.txt","app/missing.txt"},(i,n)=>{});}catch{failed=true;}if(!failed||File.ReadAllText(Path.Combine(target,"app/a.txt"))!="old")throw new Exception("rollback failed");}}
class UpdateForm:Form {
string root;int parentPid;bool localTest,busy,installing;Manifest manifest;List<string> files;FileStream updateLock;TextBox url=new TextBox();TextBox notes=new TextBox();Label phase=new Label(),detail=new Label();ProgressBar progress=new ProgressBar();Button check=new Button(),start=new Button();CheckBox restart=new CheckBox();JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=1024*1024};HttpClient client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=true,MaxAutomaticRedirections=8}){Timeout=TimeSpan.FromMinutes(30)};string settings;
public UpdateForm(string[] args){for(int i=0;i<args.Length;i++){if(args[i]=="--root"&&i+1<args.Length)root=args[++i];else if(args[i]=="--pid"&&i+1<args.Length)int.TryParse(args[++i],out parentPid);else if(args[i]=="--allow-local-test")localTest=true;}if(root==null)root=AppDomain.CurrentDomain.BaseDirectory;root=Path.GetFullPath(root);settings=Path.Combine(root,"UserData","update-settings.json");Text="轻摘 · 更新程序";Size=new Size(740,570);MinimumSize=new Size(620,500);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",10);BackColor=Color.White;var panel=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(28),ColumnCount=1,RowCount=10};panel.RowStyles.Add(new RowStyle(SizeType.Absolute,45));panel.Controls.Add(new Label{Text="软件更新",Font=new Font(Font.FontFamily,22,FontStyle.Bold),AutoSize=true});panel.Controls.Add(new Label{Text="GitHub更新清单地址（latest.json）",AutoSize=true});url.Dock=DockStyle.Fill;panel.Controls.Add(url);panel.Controls.Add(new Label{Text="上传GitHub Release后填入：https://github.com/用户名/仓库/releases/latest/download/latest.json",AutoSize=true,MaximumSize=new Size(650,0),ForeColor=Color.DimGray});var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,Height=45};check.Text="检查更新";check.AutoSize=true;start.Text="下载并安装更新";start.AutoSize=true;start.Enabled=false;check.Click+=async delegate{await Check();};start.Click+=async delegate{await Install();};buttons.Controls.Add(check);buttons.Controls.Add(start);panel.Controls.Add(buttons);phase.Text="尚未检查更新";phase.AutoSize=true;panel.Controls.Add(phase);progress.Dock=DockStyle.Fill;progress.Height=14;panel.Controls.Add(progress);detail.AutoSize=true;panel.Controls.Add(detail);notes.Dock=DockStyle.Fill;notes.Multiline=true;notes.ReadOnly=true;notes.ScrollBars=ScrollBars.Vertical;notes.Height=130;panel.RowStyles.Clear();for(int i=0;i<9;i++)panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));panel.RowStyles.Add(new RowStyle(SizeType.Percent,100));panel.Controls.Add(notes);restart.Text="更新完成后重新启动主程序";restart.Checked=true;restart.AutoSize=true;panel.Controls.Add(restart);Controls.Add(panel);if(File.Exists(settings))try{var c=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(settings));url.Text=Convert.ToString(c["manifestUrl"]);}catch{}FormClosing+=(s,e)=>{if(installing){e.Cancel=true;MessageBox.Show("正在更换文件，请等待完成。","更新中");}else if(busy){e.Cancel=true;MessageBox.Show("正在下载或校验，请等待完成。","更新中");}};}
void UI(string text,int value){phase.Text=text;progress.Style=ProgressBarStyle.Blocks;progress.Value=Math.Max(0,Math.Min(100,value));}
string Current(){try{var o=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"version.json")));return Convert.ToString(o["version"]);}catch{return "1.0.0";}}
async Task Check(){if(busy)return;busy=true;check.Enabled=false;start.Enabled=false;try{if(!Core.Url(url.Text.Trim(),localTest))throw new Exception("请填写HTTPS更新清单地址");UI("正在获取更新清单…",0);string manifestFile=Path.Combine(root,"UserData","updates","manifest-"+Guid.NewGuid().ToString("N")+".json");Directory.CreateDirectory(Path.GetDirectoryName(manifestFile));await Core.NodeDownload(root,json,localTest,url.Text.Trim(),manifestFile,1024*1024,null);string text=File.ReadAllText(manifestFile);manifest=json.Deserialize<Manifest>(text);Core.Validate(manifest,localTest);Directory.CreateDirectory(Path.GetDirectoryName(settings));File.WriteAllText(settings,json.Serialize(new{manifestUrl=url.Text.Trim()}),Encoding.UTF8);notes.Text=manifest.releaseNotes??"";if(Core.VersionOf(manifest.version)<=Core.VersionOf(Current())){UI("已是最新版本 v"+Current(),100);detail.Text="清单版本：v"+manifest.version;}else{UI("发现新版本 v"+manifest.version,0);detail.Text="当前 v"+Current()+" → v"+manifest.version+" · "+MB(manifest.size)+" MB";start.Enabled=true;}}catch(Exception e){UI("检查失败",0);detail.Text=e.Message;}finally{busy=false;check.Enabled=true;}}
async Task DownloadPackage(Manifest m,string zip,Action<string,long,double> report){await Core.NodeDownload(root,json,localTest,m.packageUrl,zip,m.size,(received,rate)=>report("download",received,rate));if(new FileInfo(zip).Length!=m.size)throw new Exception("下载包大小与清单不一致");report("verify",m.size,0);string digest=await Task.Run(()=>Core.Hash(zip));if(!digest.Equals(m.sha256,StringComparison.OrdinalIgnoreCase))throw new Exception("完整性校验失败，主程序未关闭，文件未更换");report("verified",m.size,0);}
static string MB(long n){return (n/1048576.0).ToString("0.00");}
async Task Install(){if(busy||manifest==null)return;if(MessageBox.Show("下载校验完成后会关闭主程序并安装更新。已保存的UserData会保留。是否继续？","安装更新",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;busy=true;check.Enabled=start.Enabled=false;string work=Path.Combine(root,"UserData","updates",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(work);string zip=Path.Combine(work,"package.zip"),stage=Path.Combine(work,"stage"),backup=Path.Combine(work,"backup");try{updateLock=new FileStream(Path.Combine(root,"UserData","updates","install.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);UI("正在下载更新包…",0);await DownloadPackage(manifest,zip,(stageName,received,rate)=>{if(stageName=="download"){UI("正在下载更新包…",(int)(received*100/manifest.size));detail.Text=MB(received)+" / "+MB(manifest.size)+" MB · "+(rate/1048576).ToString("0.00")+" MB/s";}else if(stageName=="verify"){UI("正在校验SHA-256…",100);detail.Text="只有大小与SHA-256一致才安装";}});UI("完整性通过，正在安全解包…",100);files=await Task.Run(()=>Core.Extract(zip,stage));var embedded=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(stage,"version.json")));if(Core.VersionOf(Convert.ToString(embedded["version"]))!=Core.VersionOf(manifest.version))throw new Exception("更新包内版本号与清单不一致");foreach(string file in files)Core.SafePath(root,file);UI("校验通过，正在关闭主程序…",100);await CloseMain();installing=true;UI("正在更换程序文件…",0);await Task.Run(()=>Core.Apply(root,stage,backup,files,(done,total)=>{BeginInvoke((Action)(()=>{UI("正在更换程序文件…",done*100/total);detail.Text=done+" / "+total+" 个文件";}));}));installing=false;UI("更新完成 v"+manifest.version,100);detail.Text="任务、报告及浏览器登录资料已保留。";if(restart.Checked&&MessageBox.Show("更新成功，是否现在重新启动轻摘？","更新完成",MessageBoxButtons.YesNo)==DialogResult.Yes){Process.Start(new ProcessStartInfo(Path.Combine(root,"轻摘.exe")){UseShellExecute=true,WorkingDirectory=root});CloseAfter();}else MessageBox.Show("更新完成，可稍后手动启动。","轻摘更新");}catch(Exception e){installing=false;UI("更新未完成",0);detail.Text=e.Message;notes.Text=e.ToString();File.WriteAllText(Path.Combine(work,"error.log"),e.ToString());}finally{if(updateLock!=null){updateLock.Dispose();updateLock=null;}busy=false;check.Enabled=true;}}
void CloseAfter(){busy=false;Close();}
async Task CloseMain(){string exe=Path.GetFullPath(Path.Combine(root,"轻摘.exe"));if(!File.Exists(exe))throw new Exception("目标目录不是有效的软件目录");var targets=new List<Process>();foreach(var proc in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(exe))){try{if(Path.GetFullPath(proc.MainModule.FileName).Equals(exe,StringComparison.OrdinalIgnoreCase))targets.Add(proc);}catch{}}if(parentPid>0)try{var parent=Process.GetProcessById(parentPid);if(Path.GetFullPath(parent.MainModule.FileName).Equals(exe,StringComparison.OrdinalIgnoreCase)&&!targets.Exists(x=>x.Id==parent.Id))targets.Add(parent);}catch{}foreach(var p in targets){p.CloseMainWindow();for(int i=0;i<100&&!p.HasExited;i++)await Task.Delay(200);if(!p.HasExited)throw new Exception("主程序尚未退出，请保存并关闭主程序后重试");}await Task.Delay(1500);}
}
}
